function canSend(history, now, limit, windowMs) {
  const cutoff = now - windowMs;
  let i = 0;
  while (i < history.length && history[i] <= cutoff) i++;  // history is in time order
  history.splice(0, i);                                   // prune expired sends
  if (history.length >= limit) return false;
  history.push(now);
  return true;
}

const DAY = 86_400_000;
const h = [];
canSend(h, 0, 2, DAY);        // true
canSend(h, 1000, 2, DAY);     // true
canSend(h, 2000, 2, DAY);     // false (2 already in window)
canSend(h, DAY + 1, 2, DAY);  // true (both earlier sends expired)
```
